 SplitContainer companionSide;WorkTab companionSideTab;bool changingCompanionSide;
 void CloseCompanionDock(){if(companionSide==null)return;var split=companionSide;var tab=companionSideTab;companionSide=null;companionSideTab=null;split.Panel1.Controls.Remove(tabs);if(tab!=null&&!tab.panel.IsDisposed){split.Panel2.Controls.Remove(tab.panel);if(!tab.page.IsDisposed)tab.page.Controls.Add(tab.panel);}Controls.Remove(split);Controls.Add(tabs);tabs.BringToFront();split.Dispose();if(tab!=null)ResizeTab(tab);}
 async Task DockCompanion(WorkTab tab,TabPage previous){if(companionSideTab==tab){if(previous!=tab.page)tabs.SelectedTab=previous;return;}CloseCompanionDock();if(compare!=null&&(compare==tab||comparePanel==tab.panel))EndCompare();companionSideTab=tab;companionSide=new SplitContainer{Size=new Size(Math.Max(900,ClientSize.Width),ClientSize.Height),Dock=DockStyle.Fill,Orientation=Orientation.Vertical,Panel1MinSize=500,Panel2MinSize=300,FixedPanel=FixedPanel.Panel2};Controls.Remove(tabs);companionSide.Panel1.Controls.Add(tabs);tab.panel.Parent.Controls.Remove(tab.panel);companionSide.Panel2.Controls.Add(tab.panel);Controls.Add(companionSide);companionSide.BringToFront();companionSide.SplitterDistance=Math.Max(500,companionSide.Width-390);changingCompanionSide=true;try{tabs.SelectedTab=previous!=null&&previous!=tab.page&&tabs.TabPages.Contains(previous)?previous:home;}finally{changingCompanionSide=false;}ResizeTab(tab);await SelectTab();SetStatus("Companion stays beside your tabs. Drag the divider; choose its tab for the full view, or Companion > Float over your work.");}
 async Task<WorkTab> EnsureCompanion(){if(CompanionOwnedElsewhere())return null;var tab=items.FirstOrDefault(t=>t.studio=="companion");if(tab==null){var detached=detachedItems.FirstOrDefault(t=>t.studio=="companion"&&t.process!=null&&!t.process.HasExited);if(detached!=null){await Reattach(detached);tab=detached;}else{tab=Add("companion");if(tab==null)return null;}}if(tab.process==null||tab.process.HasExited){tab.process=null;tab.attached=false;Start(tab);}for(int i=0;i<120&&!tab.attached;i++){await Tick();await Task.Delay(100);}if(!tab.attached||tab.process==null||tab.process.HasExited){SetStatus("Companion could not attach. Quit an older Companion from its tray menu and try again, or select the current version in Manage studios.");return null;}return tab;}
 async Task FloatCompanion(){var previous=tabs.SelectedTab;CloseCompanionDock();var tab=await EnsureCompanion();if(tab==null)return;tabs.SelectedTab=tab.page;await Detach();if(!tab.detached)return;string ack=Path.Combine(tab.folder,"floating.json");if(File.Exists(ack))File.Delete(ack);Command(tab,"float");for(int i=0;i<80&&!File.Exists(ack)&&!tab.process.HasExited;i++)await Task.Delay(100);if(File.Exists(ack)){var state=json.Deserialize<Dictionary<string,object>>(ReadShared(ack));SetStatus(Convert.ToBoolean(state["topmost"])?"Companion floats above your work. Use its Window menu to turn Always on top off.":"Companion opened; enable Always on top in its Window menu.");}else SetStatus("This running Companion did not confirm floating mode. Update Companion, then reopen it from Workscape.");if(previous!=tab.page&&tabs.TabPages.Contains(previous))tabs.SelectedTab=previous;else tabs.SelectedTab=home;}
